import { Component, Event, EventEmitter, Host, Prop, h } from '@stencil/core';

/**
 * @slot default - default slot for the lists
 */
@Component({
  tag: 'groupui-list',
  styleUrl: 'list.scss',
  shadow: false,
})
export class List {
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly hover: boolean;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <slot />
      </Host>
    );
  }
}
